// Des: Command dispatch: status, fetch, run, export, canary, kill
// Flo: parse args > build context > route by command word > each command prints text or --json > returns exit code
// I/O: process Init (main) > exit code 0-4; stdout results
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const targ = @import("ct-ctrl-args.zig"); const runz = @import("ct-ctrl-runz.zig"); const clou = @import("ct-ctrl-clou.zig"); const exit = @import("ct-exit-code.zig"); const cfgz = @import("cf-conf-load.zig"); const urln = @import("ut-urlz-norm.zig"); const ladd = @import("ru-tier-ladd.zig"); const fron = @import("qu-fron-main.zig"); const kill = @import("ru-kill-swit.zig"); const spen = @import("ru-spen-guar.zig"); const base = @import("nt-vend-base.zig"); const pipe = @import("ru-page-fetc.zig"); const brwx = @import("ct-ctrl-brow.zig"); const strx = @import("ct-ctrl-strm.zig");
const CF = .{ .vers = "0.1.0", .help = "scra " ++ "0.1.0 - cheapest good page, free first\n  status [--json]                      read-only\n  fetch <url> [--live [--force]]       dry-run unless --live; --force allows paid spend\n  run [url] [--seed-file f] [--sitemap u] [--decl n] [--live [--force]]\n  export [--format jsonl|csv] [--out file]\n  canary [--add url] [--live]\n  kill [--on|--off]                    stop or allow all vendor spend\n  sync [--live]                        upload to the cloud (local first), purge at 90%\n  login <name>                         owner logs in by hand in own Chrome profile (logi_mode_enab + brow_enab)\n  fetch options: --geoz cc --wait ms --selector css --scroll n --click text --consent --steps f.json --account name\nexit: 0 ok, 1 fail, 2 usage, 3 drift, 4 blocked" };
const Vst = struct { vend: []const u8, used: i64, free: u32, okay: i64, tota: i64 };
const Stat = struct { appz: []const u8, vers: []const u8, mode: []const u8, kill: bool, capz_micr: u64, spen_micr: i64, disk_gbyt: u32, clou_mode: []const u8, logi_enab: bool, data_path: []const u8, vend_orde: []const []const u8, vendz: []const Vst, pend: i64, done: i64, dead: i64, pags: i64 };
const Dryf = struct { mode: []const u8, urlz: []const u8, tiers: []const u8, worst_cred: u32, worst_micr: u64, note: []const u8 };
fn cnt(dbzz: *@import("st-stor-sqli.zig").Db, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colInt(0); }
fn vstat(ctx: *const cx.Ctx, dbzz: *@import("st-stor-sqli.zig").Db, now: i64) ![]const Vst { var list: std.ArrayList(Vst) = .empty; for (ctx.conf.vend_orde) |name| { const vend = base.vendFind(name) orelse continue; var stmt = try dbzz.prep("SELECT coalesce(sum(code>=200 AND code<300),0),count(*) FROM logz WHERE vend=?1;"); defer stmt.fini(); try stmt.bindText(1, name); _ = try stmt.step(); try list.append(ctx.allo, .{ .vend = name, .used = try spen.spenUsed(dbzz, vend, now), .free = spen.freeOf(ctx.conf, vend), .okay = stmt.colInt(0), .tota = stmt.colInt(1) }); } return list.toOwnedSlice(ctx.allo); }
fn runStat(ctx: *const cx.Ctx) !u8 { const conf = ctx.conf; var stat: Stat = .{ .appz = "scra", .vers = CF.vers, .mode = "read-only", .kill = false, .capz_micr = cfgz.capzMicr(conf), .spen_micr = 0, .disk_gbyt = conf.capz_disk_gbyt, .clou_mode = conf.clou_poli_mode, .logi_enab = conf.logi_mode_enab, .data_path = conf.data_dirz_path, .vend_orde = conf.vend_orde, .vendz = &.{}, .pend = 0, .done = 0, .dead = 0, .pags = 0 };
if (cx.dbHave(ctx)) { var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); const now = pipe.nowMs(ctx.iozz); stat.kill = try kill.killGet(&dbzz); stat.spen_micr = try spen.spenTota(&dbzz, now); stat.vendz = try vstat(ctx, &dbzz, now); stat.pend = try fron.fronCont(&dbzz, 0); stat.done = try fron.fronCont(&dbzz, 1); stat.dead = try fron.fronCont(&dbzz, 2); stat.pags = try cnt(&dbzz, "SELECT count(*) FROM page;"); }
const plain = try std.fmt.allocPrint(ctx.allo, "scra {s} | {s} | kill {} | spend {d}/{d} micro-USD | pages {d} | queue {d} pending {d} dead | disk cap {d} GB", .{ stat.vers, stat.mode, stat.kill, stat.spen_micr, stat.capz_micr, stat.pags, stat.pend, stat.dead, stat.disk_gbyt }); try cx.outz(ctx, try cx.jsonOr(ctx, stat, plain)); return 0; }
fn runFetc(ctx: *const cx.Ctx) !u8 { if (ctx.args.urlz.len == 0) return error.BadUsage; const norm = urln.urlNorm(ctx.allo, ctx.args.urlz) catch return error.BadUsage;
if (!ctx.args.live) { const est = runz.estWorst(ctx.conf, ctx.args.geoz); const dry: Dryf = .{ .mode = "dry-run", .urlz = norm, .tiers = "T1 own GET (free) > T2 vendor plain > T3 render > T4 premium", .worst_cred = est.cred, .worst_micr = est.micr, .note = "vendors only if own GET is blocked; paid only with --live --force; nothing written" }; try cx.outz(ctx, try cx.jsonOr(ctx, dry, try std.fmt.allocPrint(ctx.allo, "dry-run | {s} | T1 own GET free | worst case {d} vendor credits ({d} micro-USD) | add --live to run", .{ norm, est.cred, est.micr }))); return 0; }
if (ctx.args.strm.len > 0) return strx.runStrm(ctx); var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); var real = try cx.realMake(ctx); var brw = try brwx.brwMake(ctx, ctx.args.acct); defer if (brw) |*bwz| bwz.deinit(); var lad: ladd.Ladd = .{ .gpaz = ctx.init.gpa, .iozz = ctx.iozz, .conf = ctx.conf, .dbzz = &dbzz, .dirz = ctx.dirz, .back = real.backend(), .go = ctx.args.forc, .geoz = ctx.args.geoz, .wait = ctx.args.wait, .sele = ctx.args.sele, .acts = try brwx.actsOf(ctx), .acct = ctx.args.acct, .sess = if (brw) |*bwz| bwz else null }; const outc = try ladd.laddFetc(&lad, ctx.allo, ctx.args.urlz); const plain = try std.fmt.allocPrint(ctx.allo, "{s} | {d} | T{d} {s} | {s} | {s}", .{ outc.stat, outc.code, outc.tier, outc.vend, outc.urlz, outc.hexz }); try cx.outz(ctx, try cx.jsonOr(ctx, outc, plain)); return exit.outcCode(outc.stat, outc.code); }
fn runKill(ctx: *const cx.Ctx) !u8 { var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); if (ctx.args.onzz) try kill.killSet(&dbzz, true); if (ctx.args.offz) try kill.killSet(&dbzz, false); const onzz = try kill.killGet(&dbzz); try cx.outz(ctx, try std.fmt.allocPrint(ctx.allo, "kill switch {s}", .{if (onzz) "ON: all vendor spend halted" else "off"})); return 0; }
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.argsRead(argv.items, allo); if (args.helz or std.mem.eql(u8, args.cmdz, "help") or args.cmdz.len == 0) { try std.Io.File.stdout().writeStreamingAll(init.io, CF.help ++ "\n"); return if (args.cmdz.len == 0 and !args.helz) 2 else 0; } const ctx = try cx.ctxMake(init, args);
if (std.mem.eql(u8, args.cmdz, "status")) return runStat(&ctx); if (std.mem.eql(u8, args.cmdz, "fetch")) return runFetc(&ctx); if (std.mem.eql(u8, args.cmdz, "run")) return runz.runRun(&ctx); if (std.mem.eql(u8, args.cmdz, "export")) return runz.runExpo(&ctx); if (std.mem.eql(u8, args.cmdz, "canary")) return runz.runCana(&ctx); if (std.mem.eql(u8, args.cmdz, "kill")) return runKill(&ctx); if (std.mem.eql(u8, args.cmdz, "sync")) return clou.runSync(&ctx); if (std.mem.eql(u8, args.cmdz, "login")) return brwx.runLogin(&ctx); return error.BadUsage; }
